#!/usr/bin/env python3
import sys, os, re, gzip, io, csv, json, datetime as dt
import xml.etree.ElementTree as ET
from fractions import Fraction
from decimal import Decimal, ROUND_HALF_UP

FACT = {'kg': Fraction(1), 'g': Fraction(1, 1000),
        'lb': Fraction(45359237, 10**8), 'oz': Fraction(28349523125, 10**12)}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
COLS = {
    'east': {'id', 'type', 'shipped', 'gross', 'net', 'status', 'note'},
    'lakeside': {'id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'},
    'river': {'t', 'ref', 'shipped', 'weight', 'status'},
    'west': {'id', 'typ', 'shipped', 'weight', 'status', 'note'},
    'harbor': {'rec', 'ref', 'date', 'weight', 'state'},
}
DELIM = {'east': ',', 'lakeside': ',', 'river': '\t', 'west': ';', 'harbor': '|'}
BASE_DATE = {'east': 'YMD', 'lakeside': 'iso', 'river': 'MM/DD/YYYY',
             'west': 'DD.MM.YYYY', 'harbor': 'iso'}
HARBOR_ST = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled',
             'RET': 'returned', 'HLD': 'held'}
FW_ST = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}
MONTHS = {m: i + 1 for i, m in enumerate('jan feb mar apr may jun jul aug sep oct nov dec'.split())}


def decode(b):
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8', 'replace')
    if b[:2] in (b'\xff\xfe', b'\xfe\xff'):
        return b.decode('utf-16', 'replace')
    enc = 'utf-8'
    head = b[:2048].decode('latin1')
    for line in head.split('\n')[:15]:
        m = re.match(r'#\s*charset\s*:\s*([\w.\-]+)', line.strip(), re.I)
        if m:
            enc = m.group(1)
            break
    try:
        return b.decode(enc, 'replace')
    except LookupError:
        return b.decode('utf-8', 'replace')


def raw_bytes(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b


def lines_of(t):
    return [l[:-1] if l.endswith('\r') else l for l in t.split('\n')]


def norm_id(s):
    m = re.match(r'^\s*sh\W*0*(\d+)\s*$', s or '', re.I)
    return int(m.group(1)) if m else None


def norm_status(s):
    return re.sub(r'[\s\-]+', '_', (s or '').strip().lower())


def norm_form(f):
    f = f.strip()
    u = f.upper()
    if u in ('ISO', 'YMD', 'YYYY-MM-DD'):
        return 'iso'
    if u in ('DMY', 'DD-MM-YYYY'):
        return 'DMY'
    if u == 'SERIAL':
        return 'serial'
    return u


def parse_time(s, form):
    """Return UTC date (datetime.date)."""
    s = (s or '').strip()
    m = re.match(r'^(\d{4})-(\d\d)-(\d\d)(?:[T ](\d\d):(\d\d)(?::(\d\d)(?:\.\d+)?)?\s*(Z|[+-]\d\d:?(?:\d\d)?)?)?$', s)
    if m:
        y, mo, d = int(m[1]), int(m[2]), int(m[3])
        base = dt.datetime(y, mo, d)
        if m[4] is not None:
            base = base.replace(hour=int(m[4]), minute=int(m[5]), second=int(m[6] or 0))
            tz = m[7]
            if tz and tz != 'Z':
                sign = 1 if tz[0] == '+' else -1
                digits = tz[1:].replace(':', '')
                off = dt.timedelta(hours=int(digits[:2]), minutes=int(digits[2:4] or 0))
                base = base - sign * off
        return base.date()
    m = re.match(r'^(\d{1,2}) ([A-Za-z]{3})[a-z]* (\d{4})$', s)
    if m:
        return dt.date(int(m[3]), MONTHS[m[2].lower()], int(m[1]))
    if form == 'serial' or re.match(r'^\d{5}(\.\d+)?$', s):
        return dt.date(1899, 12, 30) + dt.timedelta(days=int(float(s)))
    m = re.match(r'^(\d{1,2})\.(\d{1,2})\.(\d{4})$', s)
    if m:
        return dt.date(int(m[3]), int(m[2]), int(m[1]))
    m = re.match(r'^(\d{1,2})([/-])(\d{1,2})\2(\d{4})$', s)
    if m:
        a, b, y = int(m[1]), int(m[3]), int(m[4])
        if form in ('DMY', 'DD/MM/YYYY'):
            return dt.date(y, b, a)
        return dt.date(y, a, b)  # MM/DD/YYYY
    m = re.match(r'^(\d{4})(\d\d)(\d\d)$', s)
    if m:
        return dt.date(int(m[1]), int(m[2]), int(m[3]))
    m = re.match(r'^(\d{4})(\d{3})$', s)
    if m:
        return dt.date(int(m[1]), 1, 1) + dt.timedelta(days=int(m[2]) - 1)
    raise ValueError('bad date %r' % s)


def parse_weight(s, unit, group_comma=True, decimal_comma=False):
    s = (s or '').strip()
    m = re.match(r'^([0-9.,\s]+?)\s*([A-Za-z]+)?$', s)
    if not m:
        raise ValueError('bad weight %r' % s)
    num, u = m.group(1), m.group(2)
    if u:
        unit = u.lower()
    num = num.replace(' ', '')
    if decimal_comma:
        num = num.replace('.', '').replace(',', '.')
    else:
        num = num.replace(',', '')
    return Fraction(Decimal(num)) * FACT[unit]


def rtype(s):
    s = (s or '').strip().lower()
    if s.startswith('c') or s.startswith('a'):
        return 'C'
    if s.startswith('v'):
        return 'V'
    return 'N'


def split_records(text):
    """yield logical lines (joining quoted multi-line), as (line, is_joined)."""
    buf = None
    for l in lines_of(text):
        if buf is not None:
            buf += '\n' + l
            if buf.count('"') % 2 == 0:
                yield buf
                buf = None
            continue
        if l.startswith('#'):
            yield l
            continue
        if l.strip() == '':
            continue
        if l.count('"') % 2:
            buf = l
        else:
            yield l
    if buf is not None:
        yield buf


def read_delimited(depot, text):
    delim = DELIM[depot]
    cols = COLS[depot]
    seq = None
    date_form = BASE_DATE[depot]
    unit = 'kg'
    header = None
    out = []
    for line in split_records(text):
        if line.startswith('#'):
            m = re.match(r'#\s*([A-Za-z][A-Za-z ]*?)\s*:\s*(.*)$', line)
            m2 = re.match(r'#\s*harbor export seq=(\d+)', line)
            if m2 and seq is None:
                seq = int(m2.group(1))
            elif m:
                k, v = m.group(1).lower(), m.group(2).strip()
                if k == 'seq':
                    if seq is None:
                        try:
                            seq = int(v)
                        except ValueError:
                            pass
                elif k in ('dates', 'date format', 'date'):
                    date_form = norm_form(v)
                elif k in ('unit', 'weight unit'):
                    mu = re.match(r'[A-Za-z]+', v)
                    if mu and mu.group(0).lower() in FACT:
                        unit = mu.group(0).lower()
            continue
        if delim == ',':
            row = next(csv.reader([line], delimiter=','))
        else:
            row = line.split(delim)
        row = [c.strip() if delim != ',' else c for c in row]
        low = [c.strip().lower() for c in row]
        if low and all(c in cols for c in low):
            header = low
            continue
        if header is None:
            continue
        rec = dict(zip(header, row)) if len(row) == len(header) else None
        rowunit = None
        wcol = {'east': 'gross', 'lakeside': 'gross_kg'}.get(depot, 'weight')
        if len(row) == len(header) + 1:
            wi = header.index(wcol)
            cand = None
            if wi + 1 < len(row) and row[wi + 1].strip().lower() in FACT:
                cand = wi + 1
            elif row[-1].strip().lower() in FACT:
                cand = len(row) - 1
            else:
                for i, c in enumerate(row):
                    if c.strip().lower() in FACT:
                        cand = i
                        break
            if cand is not None:
                rowunit = row[cand].strip().lower()
                row2 = row[:cand] + row[cand + 1:]
                rec = dict(zip(header, row2))
        if rec is None:
            # trailer / malformed
            continue
        idc = rec.get('id') or rec.get('ref') or ''
        idc2 = idc.strip()
        if depot == 'harbor' or depot == 'river':
            pass
        n = norm_id(idc2)
        if n is None:
            continue
        if depot == 'east':
            t, sh, w, st = rec['type'], rec['shipped'], rec['gross'], rec['status']
        elif depot == 'lakeside':
            t, sh, w, st = rec['kind'], rec['shipped'], rec['gross_kg'], rec['status']
        elif depot == 'river':
            t, sh, w, st = rec['t'], rec['shipped'], rec['weight'], rec['status']
        elif depot == 'west':
            t, sh, w, st = rec['typ'], rec['shipped'], rec['weight'], rec['status']
        else:
            t, sh, w, st = rec['rec'], rec['date'], rec['weight'], rec['state']
            st = HARBOR_ST.get(st.strip().upper(), st)
        ty = rtype(t)
        if ty == 'V':
            out.append((n, 'V', None))
            continue
        u = rowunit or unit
        if depot == 'lakeside':
            u = rowunit or 'kg'
        kg = parse_weight(w, u, decimal_comma=(depot == 'west'))
        if depot == 'west':
            pass
        day = parse_time(sh, 'DD.MM.YYYY' if depot == 'west' else date_form)
        out.append((n, ty, (kg, day, norm_status(st))))
    return seq, out


def read_fixed(text):
    layouts = {
        'FW1': (42, dict(id=(0, 9), type=(9, 10), shipped=(10, 17), weight=(17, 25), status=(25, 26)), 'g', 'doy'),
        'FW2': (43, dict(type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26), status=(26, 27)), 'cg', 'ymd'),
        'FW3': (41, dict(id=(0, 9), shipped=(9, 16), type=(16, 17), weight=(17, 24), status=(24, 25)), 'dl', 'doy'),
    }
    bylen = {v[0]: k for k, v in layouts.items()}
    cur = None
    seq = None
    out = []
    for line in lines_of(text):
        if '\f' in line:
            continue
        if line.startswith('#'):
            m = re.match(r'#LAYOUT\s+(\w+)', line)
            if m:
                cur = m.group(1).upper()
            m = re.match(r'#SEQ\s+(\d+)', line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if line.strip() == '':
            continue
        if re.search(r'DEPOT SHIPMENT LISTING', line):
            continue
        name = bylen.get(len(line), cur)
        if name is None or name not in layouts:
            continue
        L, f, wu, df = layouts[name]
        if len(line) != L:
            line = line.ljust(L)[:L]
        g = {k: line[a:b] for k, (a, b) in f.items()}
        n = norm_id(g['id'].strip())
        if n is None:
            continue
        ty = rtype(g['type'])
        if ty == 'V':
            out.append((n, 'V', None))
            continue
        w = int(g['weight'])
        if wu == 'g':
            kg = Fraction(w, 1000)
        elif wu == 'cg':
            kg = Fraction(w, 100)
        else:
            kg = Fraction(w, 10) * FACT['lb']
        s = g['shipped'].strip()
        day = parse_time(s, '')
        out.append((n, ty, (kg, day, FW_ST.get(g['status'].strip().upper(), g['status'].strip().lower()))))
    return seq, out


def read_xml(b):
    root = ET.fromstring(b)
    seq = int(root.get('seq')) if root.get('seq') else None
    runit = (root.get('weight-unit') or 'kg').lower()
    out = []
    for el in root.iter('shipment'):
        n = norm_id(el.get('id'))
        if n is None:
            continue
        ty = rtype(el.get('type'))
        if ty == 'V':
            out.append((n, 'V', None))
            continue

        def get(name):
            c = el.find(name)
            if c is not None and c.text is not None:
                return c.text.strip()
            return el.get(name)
        we = el.find('weight')
        wtxt = get('weight')
        u = runit
        if we is not None and we.get('unit'):
            u = we.get('unit').lower()
        elif el.get('unit'):
            u = el.get('unit').lower()
        kg = parse_weight(wtxt, u)
        day = parse_time(get('shipped'), '')
        out.append((n, ty, (kg, day, norm_status(get('status')))))
    return seq, out


def read_json(text):
    seq = None
    out = []
    for line in lines_of(text):
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        v = json.loads(line)
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if seq is None and o['meta'].get('seq') is not None:
                    seq = int(o['meta']['seq'])
                continue
            n = norm_id(str(o.get('id', '')))
            if n is None:
                continue
            ty = rtype(o.get('kind'))
            if ty == 'V':
                out.append((n, 'V', None))
                continue
            kg = None
            for k, val in o.items():
                m = re.match(r'^weight_(kg|g|lb|oz)$', k, re.I)
                if m:
                    kg = parse_weight(str(val), m.group(1).lower())
            if kg is None and 'weight' in o:
                kg = parse_weight(str(o['weight']), str(o.get('unit', 'kg')).lower())
            day = parse_time(o.get('shipped_at'), '')
            out.append((n, ty, (kg, day, norm_status(o.get('status')))))
    return seq, out


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split('-')[0]
        exports.setdefault(depot, [])
        b = raw_bytes(p)
        stripped = b.lstrip(b'\xef\xbb\xbf\xff\xfe\xfe')
        if depot in COLS:
            seq, recs = read_delimited(depot, decode(b))
        elif depot == 'south':
            seq, recs = read_fixed(decode(b))
        elif depot == 'central':
            seq, recs = read_xml(b)
        elif depot == 'north':
            seq, recs = read_json(decode(b))
        else:
            # unknown depot: sniff
            t = decode(b)
            s = t.lstrip()
            if s.startswith('<'):
                seq, recs = read_xml(b)
            elif s.startswith('{') or s.startswith('['):
                seq, recs = read_json(t)
            else:
                continue
        exports[depot].append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for depot, exps in exports.items():
        cur = {}
        for seq, name, recs in sorted(exps, key=lambda e: (e[0], e[1])):
            for n, ty, val in recs:
                if ty == 'N':
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = val
                elif ty == 'C':
                    cur[n] = val
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    rank = {d: i for i, d in enumerate(ORDER)}
    depots_sorted = sorted(current, key=lambda d: (rank.get(d, 99), d))
    owners = {}
    for d in depots_sorted:
        for n in current[d]:
            owners.setdefault(n, []).append(d)
    handovers = sum(1 for v in owners.values() if len(v) > 1)

    dep = {d: [0, Fraction(0)] for d in exports}
    months = {}
    for n, ds in owners.items():
        d = ds[0]
        kg, day, st = current[d][n]
        if st in ('delivered', 'delivered_late'):
            dep[d][0] += 1
            dep[d][1] += kg
            mk = '%04d-%02d' % (day.year, day.month)
            m = months.setdefault(mk, [0, Fraction(0)])
            m[0] += 1
            m[1] += kg

    def r2(f):
        d = Decimal(f.numerator) / Decimal(f.denominator)
        return float(Decimal(f.numerator * 10**30 // f.denominator) / Decimal(10**30)
                     .quantize(Decimal('1'))) if False else float(
            (Fraction(f.numerator, f.denominator) * 100 + Fraction(1, 2)).__floor__() / 100) \
            if f >= 0 else float(round(f, 2))

    res = {
        'depots': {d: {'shipments': dep[d][0], 'total_kg': r2(dep[d][1])} for d in sorted(dep)},
        'months': {k: {'shipments': months[k][0], 'total_kg': r2(months[k][1])} for k in sorted(months)},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as f:
        json.dump(res, f, indent=2)
        f.write('\n')


main()
